const unread = await notificationRepo.listUnreadSince(
  orgId,
  recipientId,
  windowStart,
);

// Evaluated at build time, so a notification created before the mute is
// left out and stays unread. After an unmute it can still make a later
// digest while it remains inside the window. The cap applies to what remains.
const mutedProjectIds = new Set(
  await muteRepo.listMutedProjectIds(orgId, recipientId),
);

const entries: DigestEntry[] = unread
  .filter((notification) => notification.createdAt <= windowEnd)
  .filter(
    (notification) =>
      notification.projectId == null ||
      !mutedProjectIds.has(notification.projectId),
  )
  .map((notification) => ({
    notificationId: notification.id,
    kind: notification.kind,
    title: notification.title,
    href: notification.href,
    occurredAt: notification.createdAt,
  }))
  .slice(0, DIGEST_MAX_ENTRIES);

