/**
 * Stops this member's day-to-day traffic for one project. Idempotent, and it
 * changes only the actor's own mute. Guarded the same way as reading the project.
 */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await requireReadableProject(actor, orgId, projectId);
  await muteRepo.mute(orgId, actor.userId, project.id);
}

/** Lifts the actor's mute on a project. Idempotent, and only their own row. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await requireReadableProject(actor, orgId, projectId);
  await muteRepo.unmute(orgId, actor.userId, project.id);
}

/** The actor's own muted projects in `orgId`. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return muteRepo.listMutedProjectIds(orgId, actor.userId);
}

