import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { NotFoundError } from "@/server/services/_support";
import { buildDigest } from "@/server/services/digest-service";
import {
  listMutedProjectIds,
  listNotifications,
  muteProject,
  notify,
  unmuteProject,
} from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import * as issueService from "@/server/services/issue-service";
import * as projectRepo from "@/server/repositories/project-repository";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("mute", "growth");
});

afterAll(() => {
  cleanup();
});

async function listed(recipient: Actor["userId"], kind?: "comment_created" | "comment_mention" | "issue_assigned" | "issue_overdue" | "member_joined") {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: kind ? [kind] : undefined,
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("project mutes", () => {
  it("mutes idempotently and lists only the actor's projects", async () => {
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#000000",
      targetDate: null,
    });

    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    await muteProject(tenant.actors.admin, tenant.org.id, other.id);

    const memberMutes = await listMutedProjectIds(tenant.actors.member, tenant.org.id);
    expect(memberMutes).toEqual([tenant.project.id]);

    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    expect(await listMutedProjectIds(tenant.actors.member, tenant.org.id)).toEqual([]);

    expect(await listMutedProjectIds(tenant.actors.admin, tenant.org.id)).toEqual([other.id]);
    await unmuteProject(tenant.actors.admin, tenant.org.id, other.id);
  });

  it("rejects a foreign org, a missing project, and a role without project:read", async () => {
    const other = await createTenant("mute-other", "growth");
    await expect(
      muteProject(tenant.actors.member, other.org.id, other.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      listMutedProjectIds(tenant.actors.member, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      muteProject(tenant.actors.member, tenant.org.id, "missing" as ProjectId),
    ).rejects.toBeInstanceOf(NotFoundError);

    const outsider = {
      ...tenant.actors.member,
      role: "guest" as Actor["role"],
    };
    await expect(
      unmuteProject(outsider, tenant.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("suppresses non-personal kinds and strips email from personal ones", async () => {
    await muteProject(tenant.actors.admin, tenant.org.id, tenant.project.id);

    const assigned = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin, tenant.userIds.viewer], {
      title: "Assigned",
      body: "yours",
      href: "/issues/1",
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
    });
    expect(assigned.map((row) => [row.recipientId, row.channels, row.projectId])).toEqual([
      [tenant.userIds.admin, ["in_app"], tenant.project.id],
      [tenant.userIds.viewer, ["in_app", "email"], tenant.project.id],
    ]);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_overdue",
      inApp: false,
      email: true,
      digestOnly: false,
    });
    const overdue = await notify(tenant.org.id, "issue_overdue", [tenant.userIds.admin], {
      title: "Overdue",
      body: "late",
      href: "/issues/1",
      actorId: null,
      projectId: tenant.project.id,
    });
    expect(overdue).toEqual([]);

    const comments = await notify(tenant.org.id, "comment_created", [tenant.userIds.admin, tenant.userIds.viewer], {
      title: "Comment",
      body: "hi",
      href: "/issues/1",
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
    });
    expect(comments.map((row) => row.recipientId)).toEqual([tenant.userIds.viewer]);

    const joined = await notify(tenant.org.id, "member_joined", [tenant.userIds.admin], {
      title: "Joined",
      body: "hi",
      href: "/settings/members",
      actorId: null,
    });
    expect(joined).toHaveLength(1);
    expect(joined[0]?.channels).toEqual(["in_app", "email"]);
    expect(joined[0]?.projectId).toBeNull();

    await unmuteProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
  });

  it("passes the project through issue and comment fan-out", async () => {
    await muteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Muted fan-out",
        assigneeId: tenant.userIds.viewer,
      }),
    );

    await emit("issue.assigned", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: null,
      assigneeId: tenant.userIds.viewer,
    });

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-mute-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.viewer, tenant.userIds.admin],
    });

    const viewerAssigned = await listed(tenant.userIds.viewer, "issue_assigned");
    expect(viewerAssigned.at(-1)?.channels).toEqual(["in_app"]);
    expect(viewerAssigned.at(-1)?.projectId).toBe(tenant.project.id);

    const viewerComments = await listed(tenant.userIds.viewer, "comment_created");
    expect(viewerComments.filter((row) => row.projectId === tenant.project.id)).toHaveLength(0);

    const viewerMentions = await listed(tenant.userIds.viewer, "comment_mention");
    expect(viewerMentions.at(-1)?.channels).not.toContain("email");

    const adminMentions = await listed(tenant.userIds.admin, "comment_mention");
    expect(adminMentions.at(-1)?.channels).toContain("email");
    expect(adminMentions.at(-1)?.projectId).toBe(tenant.project.id);

    await unmuteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
  });

  it("drops muted projects from the digest until unmuted, without marking them read", async () => {
    const now = new Date("2026-06-02T12:00:00.000Z");
    const inside = new Date(now.getTime() - 60 * 60 * 1000);
    vi.useFakeTimers();
    vi.setSystemTime(inside);
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title: "About muted",
      body: "m",
      href: "/issues/m",
      actorId: null,
      projectId: tenant.project.id,
      channels: ["in_app"],
    });
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "member_joined",
      title: "Not a project",
      body: "n",
      href: "/settings/members",
      actorId: null,
      projectId: null,
      channels: ["in_app"],
    });
    vi.useRealTimers();

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      kind: "comment_created",
      inApp: true,
      email: true,
      digestOnly: true,
    });

    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

    const windowStart = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString() as never;
    const windowEnd = now.toISOString() as never;
    const mutedBundle = await buildDigest(tenant.org.id, tenant.userIds.member, windowStart, windowEnd);
    expect(mutedBundle?.entries.map((entry) => entry.title)).toEqual(["Not a project"]);

    const stillUnread = await notificationRepo.listUnreadSince(
      tenant.org.id,
      tenant.userIds.member,
      windowStart,
    );
    expect(stillUnread.some((row) => row.title === "About muted" && row.readAt === null)).toBe(true);

    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    const openBundle = await buildDigest(tenant.org.id, tenant.userIds.member, windowStart, windowEnd);
    expect(openBundle?.entries.map((entry) => entry.title).sort()).toEqual(
      ["About muted", "Not a project"].sort(),
    );
  });

  it("applies the digest cap to what remains and sends nothing when only muted items remain", async () => {
    const solo = await createTenant("mute-cap", "growth");
    const now = new Date("2026-07-01T08:00:00.000Z");
    vi.useFakeTimers();
    vi.setSystemTime(new Date(now.getTime() - 1000));
    for (let i = 0; i < DIGEST_MAX_ENTRIES + 3; i += 1) {
      await notificationRepo.insertNotification(solo.org.id, {
        orgId: solo.org.id,
        recipientId: solo.userIds.member,
        kind: "comment_created",
        title: `keep ${i}`,
        body: "k",
        href: "/issues/k",
        actorId: null,
        projectId: null,
        channels: ["in_app"],
      });
    }
    const mutedProject = await projectRepo.insertProject({
      orgId: solo.org.id,
      name: "Quiet",
      slug: "quiet",
      key: "QUI",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#111111",
      targetDate: null,
    });
    await notificationRepo.insertNotification(solo.org.id, {
      orgId: solo.org.id,
      recipientId: solo.userIds.member,
      kind: "comment_created",
      title: "hidden",
      body: "h",
      href: "/issues/h",
      actorId: null,
      projectId: mutedProject.id,
      channels: ["in_app"],
    });
    vi.useRealTimers();

    await muteProject(solo.actors.member, solo.org.id, mutedProject.id);
    const windowStart = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString() as never;
    const windowEnd = now.toISOString() as never;
    const bundle = await buildDigest(solo.org.id, solo.userIds.member, windowStart, windowEnd);
    expect(bundle?.entries).toHaveLength(DIGEST_MAX_ENTRIES);
    expect(bundle?.entries.some((entry) => entry.title === "hidden")).toBe(false);

    const only = await createTenant("mute-empty", "growth");
    vi.useFakeTimers();
    vi.setSystemTime(new Date(now.getTime() - 1000));
    await notificationRepo.insertNotification(only.org.id, {
      orgId: only.org.id,
      recipientId: only.userIds.member,
      kind: "comment_created",
      title: "only muted",
      body: "o",
      href: "/issues/o",
      actorId: null,
      projectId: only.project.id,
      channels: ["in_app"],
    });
    vi.useRealTimers();
    await muteProject(only.actors.member, only.org.id, only.project.id);
    const empty = await buildDigest(only.org.id, only.userIds.member, windowStart, windowEnd);
    expect(empty).toBeNull();
  });

  it("does not mute across orgs", async () => {
    void (null as OrgId | null);
  });
});

